removeFromDatasource(toRemove: number, byIndex = false) {
  const indexToRemove = byIndex
    ? toRemove - Math.min(this.MIN, 0) // shift!
    : this.data.findIndex(({ id }) => id === toRemove);
  if (indexToRemove >= 0) {
    this.data.splice(indexToRemove, 1);
  }
  this.MAX--;
}

